record.field:
_logger.info('Webhook actualizar tienda.')
try:
    endpoint = env['solt.api.endpoint'].search([('code', '=', 'STORE')])
    if not endpoint:
        _logger.info('Endpoint con código STORE no configurado, para actualizar y asociar empresa de odoo con una tienda de Tiendanube.')
        raise UserError('Endpoint con código STORE no configurado, para actualizar y asociar empresa de odoo con una tienda de Tiendanube.')
    main_lang = payload.get('main_language')
    main_currency_code = payload.get('main_currency')
    country_code = payload.get('country')
    if main_lang and country_code:
        lang_code = '{}_{}'.format(main_lang, country_code)
        res_lang_id = env['res.lang'].with_context(active_test=False).sudo().search([('code', '=', lang_code)], limit=1)
        if res_lang_id:
            if not res_lang_id.active:
                res_lang_id.write({'active': True})
                _logger.info('Idioma principal {} activado en Odoo.'.format(lang_code))
            else:
                _logger.info('Idioma principal {} ya está activo.'.format(lang_code))
        else:
            _logger.warning('Idioma principal {} no encontrado en res.lang. Debe cargarse en Odoo.'.format(lang_code))
    if main_currency_code:
        main_currency = env['res.currency'].with_context(active_test=False).sudo().search([('name', '=', main_currency_code)], limit=1)
        if main_currency:
            if not main_currency.active:
                main_currency.write({'active': True})
                _logger.info('Moneda principal {} activada en Odoo.'.format(main_currency_code))
            else:
                _logger.info('Moneda principal {} ya está activa.'.format(main_currency_code))
        else:
            _logger.warning('Moneda principal {} no encontrada en res.currency. Debe cargarse en Odoo.'.format(main_currency_code))
    langs = payload.get('languages', {})
    for lang_code, lang_data in langs.items():
        if lang_data.get('active') and country_code:
            full_lang_code = '{}_{}'.format(lang_code, country_code)
            res_lang_id = env['res.lang'].with_context(active_test=False).sudo().search([('code', '=', full_lang_code)], limit=1)
            if res_lang_id:
                if not res_lang_id.active:
                    res_lang_id.write({'active': True})
                    _logger.info('Idioma {} activado en Odoo.'.format(full_lang_code))
            else:
                _logger.warning('Idioma {} no está cargado en res.lang. Cargar manualmente si se necesita.'.format(lang_code))
            currency_code = lang_data.get('currency')
            if currency_code:
                currency = env['res.currency'].with_context(active_test=False).sudo().search([('name', '=', currency_code)], limit=1)
                if currency:
                    if not currency.active:
                        currency.write({'active': True})
                        _logger.info('Moneda {} activada por idioma {}.'.format(currency_code, lang_code))
                else:
                    _logger.warning('Moneda {} no encontrada en res.currency.'.format(currency_code))
    mapping_config = json.loads(endpoint.response_mapping)
    values = endpoint._process_simple_mapping_to_odoo(mapping_config, payload, record)
    values['connector_id'] = base_automation.connector_id.id
    ResCompany = env['res.company'].sudo()

    # Si la multicompañia no esta activa (solo existe una compañia en la base),
    # actualizamos directamente la compañia actual. Si esta activa, buscamos por
    # nombre o email para localizar la compañia correspondiente a la tienda.
    multi_company_active = ResCompany.search_count([]) > 1

    if multi_company_active:
        company_id = ResCompany.search(['|', ('name', '=ilike', values.get('name')), ('email', '=ilike', values.get('email'))], limit=1)
        if not company_id:
            company_id = ResCompany.search([], order='id', limit=1)
            _logger.warning('Multicompañia activa: empresa no encontrada con nombre {} o email {}. Se usa la primera compañia por defecto {}; no se crea una nueva.'.format(values.get('name'), values.get('email'), company_id.name))
            company_id.partner_id.write({'x_exclud_from_sync': True})
            company_id.sudo().write(values)
            company_id.message_post(body='Empresa sincronizada con tienda en Tiendanube (compañia por defecto)!')
        else:
            _logger.info('Multicompañia activa: empresa {} encontrada. Actualizar'.format(company_id.name))
            company_id.partner_id.write({'x_exclud_from_sync': True})
            company_id.sudo().write(values)
            company_id.message_post(body='Empresa sincronizada con tienda en Tiendanube!')
    else:
        company_id = env.company.sudo()
        _logger.info('Multicompañia inactiva: actualizando compañia actual {}.'.format(company_id.name))
        company_id.partner_id.write({'x_exclud_from_sync': True})
        company_id.write(values)
        company_id.message_post(body='Empresa sincronizada con tienda en Tiendanube!')
    if main_lang and country_code:
        lang_code = '{}_{}'.format(main_lang, country_code)
        res_lang_id = env['res.lang'].sudo().search([('code', '=', lang_code), ('active', '=', True)], limit=1)
        if res_lang_id:
            company_id.partner_id.write({'lang': res_lang_id.code})
            _logger.info('Asignado idioma principal {} al partner {}'.format(res_lang_id.code, company_id.partner_id.name))
    _logger.info('Tienda de TN {} sincronizada!'.format(company_id.name))

    company_id.write({'tn_provisioned': False})
    provision_cron = env.ref('solt_tiendanube.ir_cron_tn_provision', raise_if_not_found=False)
    if provision_cron:
        provision_cron.sudo()._trigger()
except Exception as e:
    msg = 'Error al ejecutar Webhook actualizar tienda.: {}'.format(str(e))
    _logger.error(msg)
    raise UserError(msg)

_logger.info('Ejecutar Webhook app/uninstalled.')
if record.external_id and record.bearer_token:
    try:
        ResCompany = env['res.company'].sudo()
        store_id = payload.get('store_id')
        if record.external_id == store_id:
            company_id = record
        else:
            company_id = ResCompany.search([('external_id', '=', store_id)])
        if company_id:
            wh_ids = env['solt.register.webhook'].search([('company_id', '=', company_id.id), ('connector_id', '=', base_automation.connector_id.id)])
            for wh_id in wh_ids:
                wh_id.write({'active': False})
            company_id.write({'bearer_token': '', 'external_id': ''})
            msg = 'La aplicación ha sido desinstalada en la tienda {}. Se ha removido el acceso a la API de Tiendanube.'.format(company_id.name)
            company_id.message_post(body=msg)
        else:
            _logger.error('Error: Empresa no encontrada con ID externo {}'.format(store_id))
        _logger.info('Ejecución del Webhook Evento: app/uninstalled finalizada.')
    except Exception as e:
        _logger.error('Error al ejecutar Webhook Evento: app/uninstalled: {}'.format(str(e)))
else:
    _logger.info('Webhook app/uninstalled. Empresa {} no esta asociada a una tienda en TN.'.format(record.name))

_logger.info('Ejecutar Webhook category/created.')
if record.external_id and record.bearer_token:
    found_categ_id = env['product.category'].search([('x_external_id', '=', payload.get('id'))])
    if not found_categ_id:
        try:
            admin_user = env.ref('base.user_admin')
            ProductCategory = env['product.category'].with_company(record).with_context(not_execute_category_base_automation=True)
            categ_id = None
            response = base_automation.with_company(record).connector_id.execute_endpoint('CATEG_SINGLE_GET', record=record, data=payload)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                categ_id = ProductCategory.with_user(admin_user).create(response['values'])
                _logger.info('Categoría {} sincronizado!.'.format(categ_id.name))
            elif response.get('status_code') == 402:
                _logger.error('Error: {}'.format(response.get('error_message', '')))
            else:
                _logger.error('Error: {}'.format(response.get('error_message', '')))
            _logger.info('Ejecución del Webhook Evento: category/created finalizada.')
            if categ_id:
                odoo_model = 'product.category'
                to_create_values = []
                created_field_names = []
                ir_model = env['ir.model'].search([('model', '=', odoo_model)], limit=1)
                if not ir_model:
                    _logger.error('El modelo {} no existe en el registro de modelos.'.format(odoo_model))
                    raise UserError('El modelo {} no existe en el registro de modelos.'.format(odoo_model))
                meta_fields = env['solt.api.meta.fields'].search([('model', '=', odoo_model)], limit=1)
                if not meta_fields:
                    _logger.error('Meta fields no configurados para el modelo {}.'.format(odoo_model))
                    raise UserError('Meta fields no configurados para el modelo {}.'.format(odoo_model))
                endpoint_code = 'CUSTOM_FIELD_CATEGORY_PROD_GET_ALL'
                _logger.info('Endpoint {}'.format(endpoint_code))
                response = base_automation.with_company(record).connector_id.execute_endpoint(endpoint_code, record=None)
                _logger.info(response)
                if isinstance(response['values'], list) and 200 <= response.get('status_code') < 300:
                    for val in response['values']:
                        meta_field_id = env['ir.model.fields'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
                        if not meta_field_id:
                            val['model_id'] = ir_model.id
                            to_create_values.append(Command.create(val))
                            created_field_names.append(val.get('name'))
                        else:
                            _logger.info('Meta field con ID Externo {} ya fue sincronizado!'.format(val['x_external_id']))
                if to_create_values:
                    meta_fields.sudo().write({'ir_meta_field_ids': to_create_values})
                    meta_fields.add_dynamic_fields_to_extended_view(odoo_model, created_field_names)
                _logger.info('Items importadas {}, Endpoint {}'.format(len(response['values']), endpoint_code))
                _logger.info('Items creados {}, Endpoint {}'.format(len(to_create_values), endpoint_code))
                response = base_automation.with_company(record).connector_id.execute_endpoint('CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES', record=categ_id)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    for response_data, val in zip(response['raw_response'], response['values']):
                        field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                        if field_odoo_id:
                            field_odoo_name = field_odoo_id.name
                            _logger.info('Campo personalizado encontrado {}'.format(field_odoo_name))
                            val.update({field_odoo_name: response_data.get('value')})
                            categ_id.write(val)
                else:
                    _logger.error('Error al ejecutar endpoint CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES: {}'.format(response.get('error_message', '')))
        except Exception as e:
            _logger.error('Error al ejecutar Webhook Evento: category/created: {}'.format(str(e)))
    else:
        _logger.info('Categoria {} encontrada con ID externo {}'.format(found_categ_id.name, found_categ_id.x_external_id))
else:
    _logger.info('Webhook category/created. Empresa {} no esta asociada a una tienda en TN.'.format(record.name))

_logger.info('Ejecutar Webhook category/updated.')
if record.external_id and record.bearer_token:
    try:
        response = base_automation.with_company(record).connector_id.execute_endpoint('CATEG_SINGLE_GET', record=record, data=payload)
        _logger.info(response)
        admin_user = env.ref('base.user_admin')
        if 200 <= response.get('status_code') < 300:
            found_categ_id = env['product.category'].search([('x_external_id', '=', payload.get('id'))])
            if not found_categ_id:
                found_categ_id = env['product.category'].sudo().with_context(not_execute_category_base_automation=True).create(response['values'])
                _logger.info('Categoría {} sincronizado!.'.format(found_categ_id.name))
            elif found_categ_id.can_sync_from_store():
                found_categ_id.with_context(not_execute_category_base_automation=True).write(response['values'])
                _logger.info('Categoría {} sincronizado!.'.format(found_categ_id.name))
            else:
                _logger.info('Categoría {} ya está siendo sincronizada desde Odoo, saltando sincronización.'.format(found_categ_id.id))
            if found_categ_id:
                odoo_model = 'product.category'
                to_create_values = []
                created_field_names = []
                ir_model = env['ir.model'].search([('model', '=', odoo_model)], limit=1)
                if not ir_model:
                    _logger.error('El modelo {} no existe en el registro de modelos.'.format(odoo_model))
                    raise UserError('El modelo {} no existe en el registro de modelos.'.format(odoo_model))
                meta_fields = env['solt.api.meta.fields'].search([('model', '=', odoo_model)], limit=1)
                if not meta_fields:
                    _logger.error('Meta fields no configurados para el modelo {}.'.format(odoo_model))
                    raise UserError('Meta fields no configurados para el modelo {}.'.format(odoo_model))
                endpoint_code = 'CUSTOM_FIELD_CATEGORY_PROD_GET_ALL'
                _logger.info('Endpoint {}'.format(endpoint_code))
                response = base_automation.with_company(record).connector_id.execute_endpoint(endpoint_code, record=None)
                _logger.info(response)
                if isinstance(response['values'], list) and 200 <= response.get('status_code') < 300:
                    for val in response['values']:
                        meta_field_id = env['ir.model.fields'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
                        if not meta_field_id:
                            val['model_id'] = ir_model.id
                            to_create_values.append(Command.create(val))
                            created_field_names.append(val.get('name'))
                        else:
                            _logger.info('Meta field con ID Externo {} ya fue sincronizado!'.format(val['x_external_id']))
                if to_create_values:
                    meta_fields.sudo().write({'ir_meta_field_ids': to_create_values})
                    meta_fields.add_dynamic_fields_to_extended_view(odoo_model, created_field_names)
                _logger.info('Items importadas {}, Endpoint {}'.format(len(response['values']), endpoint_code))
                _logger.info('Items creados {}, Endpoint {}'.format(len(to_create_values), endpoint_code))
                response = base_automation.with_company(record).connector_id.execute_endpoint('CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES', record=found_categ_id)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    for response_data, val in zip(response['raw_response'], response['values']):
                        field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                        if field_odoo_id:
                            field_odoo_name = field_odoo_id.name
                            _logger.info('Campo personalizado encontrado {}'.format(field_odoo_name))
                            val.update({field_odoo_name: response_data.get('value')})
                            found_categ_id.write(val)
                else:
                    _logger.error('Error al ejecutar endpoint CUSTOM_FIELD_CATEGORY_PROD_GET_VALUES: {}'.format(response.get('error_message', '')))
        elif response.get('status_code') == 402:
            _logger.error('Error: {}'.format(response.get('error_message', '')))
        else:
            _logger.error('Error: {}'.format(response.get('error_message', '')))
        _logger.info('Fin Webhook category/updated!.')
    except Exception as e:
        _logger.error('Webhook Categoria de productos: category/updated')
        _logger.error('Error al ejecutar endpoint CATEG_SINGLE_GET: {}'.format(str(e)))
else:
    _logger.info('Webhook category/updated. Empresa {} no esta asociada a una tienda en TN.'.format(record.name))

_logger.info('Ejecutar Webhook category/deleted.')
if record.external_id and record.bearer_token:
    found_categ_id = env['product.category'].search([('x_external_id', '=', payload.get('id'))])
    if not found_categ_id:
        _logger.info('Categoría no encontrada en odoo con el ID Externo {}'.format(payload.get('id')))
    else:
        try:
            _logger.info('Categoría {} encontrada con ID externo {}. Eliminar'.format(found_categ_id.name, found_categ_id.x_external_id))
            found_categ_id.sudo().write({'x_exclud_from_sync': True})
            found_categ_id.sudo().unlink()
        except Exception as e:
            _logger.error('Error al ejecutar Webhook Evento: category/deleted: {}'.format(str(e)))
            if found_categ_id:
                found_categ_id.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
else:
    _logger.info('Webhook category/deleted. Empresa {} no esta asociada a una tienda en TN.'.format(record.name))

_logger.info('Ejecutar Webhook product/created.')
if record.external_id and record.bearer_token:
    found_product_id = env['product.template'].search([('x_external_id', '=', payload.get('id'))])
    if not found_product_id:
        try:
            _logger.info('Company {}'.format(record.name))
            response = base_automation.with_company(record).connector_id.execute_endpoint('PRODUCT_SINGLE_GET', record=record, data=payload)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                response['values'].update({'is_being_synced': True, 'sync_source': 'store', 'sync_timestamp': datetime.datetime.now(), 'company_id': record.id, 'x_store_external_id': record.external_id})
                admin_user = env.ref('base.user_admin')
                product_template = env['product.template'].with_company(record).with_context(not_execute_product_base_automation=True)
                product_id = product_template.with_user(admin_user).create(response['values'])
                _logger.info('Producto {} sincronizado!.'.format(product_id.name))
                product_variant_ids = product_id.with_context(not_execute_product_base_automation=True).create_product_variants_from_json(response['raw_response'])
                _logger.info('Variantes creadas {}'.format(len(product_variant_ids)))
                product_id.with_context(not_execute_product_base_automation=True)._sync_product_images_from_json(response['raw_response'])
                _logger.info('Imagenes sincronizadas')
            elif response.get('status_code') == 402:
                _logger.error('Error: {}'.format(response.get('error_message', '')))
            else:
                _logger.error('Error: {}'.format(response.get('error_message', '')))
            _logger.info('Ejecución del Webhook Evento: product/created finalizada.')
        except Exception as e:
            _logger.error('Error al ejecutar Webhook Evento: product/created: {}'.format(str(e)))
    else:
        _logger.info('Producto {} encontrada con ID externo {}'.format(found_product_id.name, found_product_id.x_external_id))
else:
    _logger.info('Webhook product/created. Empresa {} no esta asociada a una tienda en TN.'.format(record.name))

_logger.info('Ejecutar Webhook product/updated.')
if record.external_id and record.bearer_token:
    try:
        response = base_automation.with_company(record).connector_id.execute_endpoint('PRODUCT_SINGLE_GET', record=record, data=payload)
        _logger.info(response)
        if 200 <= response.get('status_code') < 300:
            found_product_id = env['product.template'].search([('x_external_id', '=', payload.get('id'))])
            admin_user = env.ref('base.user_admin')
            if not found_product_id:
                _logger.info('Producto no encontrado con ID externo {}.'.format(payload.get('id')))
            elif found_product_id.can_sync_from_store():
                _logger.info('Producto {} encontrada con ID externo {}. Actualizar'.format(found_product_id.name, found_product_id.x_external_id))
                found_product_id = found_product_id.with_company(record).with_context(not_execute_product_base_automation=True)
                found_product_id.with_user(admin_user).write(response['values'])
                if isinstance(response['raw_response'], dict) and found_product_id.product_brand_id:
                    found_product_id.product_brand_id.write({'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_exclud_from_sync': False, 'company_id': record.id, 'x_store_external_id': record.external_id})
                found_product_id.with_user(admin_user).with_context(not_execute_product_base_automation=True).create_product_variants_from_json(response['raw_response'])
                found_product_id.with_user(admin_user).with_context(not_execute_product_base_automation=True)._sync_product_images_from_json(response['raw_response'])
                _logger.info('Imagenes sincronizadas')
            else:
                _logger.info('Producto {} ya está siendo sincronizada desde Odoo, saltando sincronización.'.format(found_product_id.id))
        elif response.get('status_code') == 402:
            _logger.error('Error: {}'.format(response.get('error_message', '')))
        else:
            _logger.error('Error: {}'.format(response.get('error_message', '')))
    except Exception as e:
        _logger.error('Webhook Productos: producto/updated')
        _logger.error('Error al ejecutar endpoint PRODUCT_SINGLE_GET: {}'.format(str(e)))
else:
    _logger.info('Webhook producto/updated. Empresa {} no esta asociada a una tienda en TN.'.format(record.name))

_logger.info('Ejecutar Webhook product/delete.')
if record.external_id and record.bearer_token:
    found_product_id = env['product.template'].search([('x_external_id', '=', payload.get('id'))])
    if not found_product_id:
        _logger.info('Producto no encontrado en odoo con el ID Externo {}'.format(payload.get('id')))
    else:
        product_name = found_product_id.name
        try:
            found_product_id = found_product_id.with_company(record)
            _logger.info('Producto {} encontrada con ID externo {}. Eliminar'.format(found_product_id.name, found_product_id.x_external_id))
            found_product_id.sudo().write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'no', 'active': False, 'x_external_id': '', 'x_exclud_from_sync': True})
        except Exception as e:
            _logger.error('Error al ejecutar Webhook Evento: product/deleted: {}'.format(str(e)))
            if found_product_id:
                found_product_id.sudo().write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error', 'active': False, 'x_external_id': ''})
        _logger.info('Producto {} encontrada con ID externo {} ha sido eliminado o archivado'.format(product_name, payload.get('id')))
    _logger.info('Webhook product/delete finalizado...')
else:
    _logger.info('Webhook product/delete. Empresa {} no esta asociada a una tienda en TN.'.format(record.name))

_logger.info('Ejecutar Webhook order/created.')
if record.external_id and record.bearer_token and (str(record.external_id) == str(payload.get('store_id'))):
    found_so_id = env['sale.order'].search([('x_external_id', '=', payload.get('id')), ('state', 'not in', ['cancel'])])
    if not found_so_id:
        try:
            _logger.info('Company {}'.format(record.name))
            admin_user = env.ref('base.user_admin')
            response = base_automation.with_company(record).with_user(admin_user).connector_id.execute_endpoint('SALE_ORDER_GET_SINGLE', record=record, data=payload)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                order_id = env['sale.order'].with_context(mail_create_nosubscribe=True).with_company(record).with_user(admin_user).create(response['values'])
                _logger.info('Orden {} sincronizado!.'.format(order_id.name))
                if order_id:
                    order_response_dict = {str(order_id.x_external_id): response['raw_response']}
                    if order_id.state == 'draft':
                        _logger.info('Orden a confirmar {}'.format(order_id.order_number))
                        order_id.action_confirm()
                        order_id.tiendanube_sync_picking_from_order(order_response_dict)
                    _logger.info('Actualizar los campos personalizados')
                    response = base_automation.with_company(record).with_user(admin_user).connector_id.execute_endpoint('CUSTOM_FIELD_ORDERS_GET_VALUES', record=order_id)
                    _logger.info(response)
                    if 200 <= response.get('status_code') < 300:
                        for response_data, val in zip(response['raw_response'], response['values']):
                            field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                            if field_odoo_id:
                                field_odoo_name = field_odoo_id.name
