_logger.info('RA Crear Categoria de productos')
for record in records:
    if env.company.external_id and env.company.bearer_token:
        if env.context.get('not_execute_category_base_automation', False):
            _logger.info('not_execute_category_base_automation esta en el contexto. No ejecutar RA.')
            continue
        try:
            res1 = base_automation.connector_id.execute_endpoint('CATEG_CREATE', record=record)
            _logger.info(res1)
            if 200 <= res1.get('status_code') < 300:
                record.write(res1['values'])
                field_odoo_ids = env['ir.model.fields'].sudo().search([('x_external_id', 'not in', [False, '']), ('model', '=', 'product.category'), ('x_exclud_from_sync', '=', False)])
                if field_odoo_ids:
                    request_data = []
                    for field in field_odoo_ids:
                        fname = field.name
                        _logger.info(fname)
                        fvalue = record[fname]
                        field_type = record._fields[fname].type
                        _logger.info(field_type)
                        if field_type in ('date', 'datetime'):
                            fvalue = fvalue.strftime('%Y-%m-%d')
                            _logger.info(fvalue)
                        request_data.append({'id': field.x_external_id, 'value': fvalue if fvalue else None})
                    if request_data:
                        _logger.info(request_data)
                        _logger.info('Endpoint CUSTOM_FIELD_CATEGORY_PRD_PUT_VALUE')
                        endpoint = env['solt.api.endpoint'].search([('code', '=', 'CUSTOM_FIELD_CATEGORY_PRD_PUT_VALUE'), ('connector_id', '=', base_automation.connector_id.id)], limit=1)
                        if not endpoint:
                            msg = 'Endpoint con código CUSTOM_FIELD_CATEGORY_PRD_PUT_VALUE no configurado, para actualizar categorías de producto.'
                            _logger.info(msg)
                            raise UserError(msg)
                        response = endpoint.execute_request(record=record, request_data=request_data)
                        _logger.info(response)
                        if 200 <= response.get('status_code') < 300:
                            record.write(response['values'])
                        elif response.get('status_code') == 402:
                            record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                            _logger.error('Error: {}'.format(response.get('error_message', '')))
                        else:
                            record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                            _logger.error('Error: {}'.format(response.get('error_message', '')))
            elif res1.get('status_code') == 402:
                record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                _logger.error('Error: {}'.format(res1.get('error_message', '')))
            else:
                record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                _logger.error('Error: {}'.format(res1.get('error_message', '')))
        except Exception as e:
            _logger.error('Error al ejecutar endpoint CATEG_CREATE: {}'.format(str(e)))
            record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
    else:
        _logger.info('RA Crear Categoria de productos. Empresa {} no esta asociada a una tienda en TN.'.format(env.company.name))

_logger.info('RA Actualizar Categoria de productos')
for record in records:
    if env.company.external_id and env.company.bearer_token and (record.x_store_external_id == env.company.external_id):
        name = record.name
        _logger.info('Actualizando Categoría de producto: {}'.format(name))
        if env.context.get('not_execute_category_base_automation', False):
            _logger.info('not_execute_category_base_automation esta en el contexto. No ejecutar RA.')
            continue
        try:
            modified_fields = base_automation.with_context(ignore_computed_fields=True)._get_trigger_fields(record)
            _logger.info('Campos a actualizar {}'.format(modified_fields))
            if modified_fields:
                endpoint = env['solt.api.endpoint'].search([('code', '=', 'CATEG_UPDATE')])
                if not endpoint:
                    _logger.info('Endpoint con código CATEG_UPDATE no configurado, para actualizar categorías de producto.')
