_logger.info('RA Crear Producto.')
for record in records:
    if env.company.external_id and env.company.bearer_token and (record.company_id == env.company):
        _logger.info('Crear Producto...')
        if env.context.get('not_execute_product_base_automation', False):
            _logger.info('not_execute_product_base_automation esta en el contexto. No ejecutar RA.')
            continue
        try:
            if record.standard_price <= 0 and record.product_variant_count == 1:
                raise UserError('El costo del producto {} es {}. El costo debe ser mayor que 0.'.format(record.name, record.standard_price))
            if not record.can_sync_to_store():
                _logger.info('Producto {} ya está siendo sincronizada desde la tienda, saltando sincronización.'.format(record.id))
                continue
            record.mark_as_syncing('odoo')
            sku_response = base_automation.connector_id.execute_endpoint('PRODUCT_SINGLE_SKU_GET', record=record)
            _logger.info('Response Endpoint PRODUCT_SINGLE_SKU_GET: {}'.format(sku_response))
            if 200 <= sku_response.get('status_code') < 300:
                _logger.info('Actualizar producto')
                val = sku_response['values']
                record.write({'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_store_external_id': env.company.external_id, **val})
                record.create_product_variants_from_json(sku_response['raw_response'], update_from_store=False)
            elif sku_response.get('status_code') == 402:
                record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                _logger.error('Error ejecutando endpoint PRODUCT_SINGLE_SKU_GET: {}'.format(sku_response.get('error_message', '')))
            elif sku_response.get('status_code') == 422 or sku_response.get('status_code') != 404:
                _logger.error('Error ejecutando endpoint PRODUCT_SINGLE_SKU_GET: {}'.format(sku_response.get('error_message', '')))
                raise UserError('Error ejecutando endpoint PRODUCT_SINGLE_SKU_GET: {}'.format(sku_response.get('error_message', '')))
            elif sku_response.get('status_code') == 404:
                _logger.info('Crear producto')
                response = base_automation.connector_id.execute_endpoint('PRODUCT_CREATE', record=record)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    record.write(response['values'])
                    if isinstance(response['raw_response'], dict) and response['raw_response'].get('brand', ''):
                        record.product_brand_id.write({'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_exclud_from_sync': False, 'x_store_external_id': env.company.external_id, 'company_id': env.company.id})
                    record.create_product_variants_from_json(response['raw_response'], update_from_store=True)
                elif response.get('status_code') == 402:
                    record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                    _logger.error('Error ejecutando endpoint PRODUCT_CREATE: {}'.format(response.get('error_message', '')))
                elif response.get('status_code') == 422 or response.get('status_code') != 404:
                    _logger.error('Error ejecutando endpoint PRODUCT_CREATE: {}'.format(response.get('error_message', '')))
                    raise UserError('Error ejecutando endpoint PRODUCT_CREATE: {}'.format(response.get('error_message', '')))
                else:
                    record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                    _logger.error('Error ejecutando endpoint PRODUCT_CREATE: {}'.format(response.get('error_message', '')))
                _logger.info('Ejecución del endpoint PRODUCT_CREATE finalizada.')
                _logger.info('Producto {} sincronizado!.'.format(record.name))
        except Exception as e:
            _logger.error('Error al ejecutar endpoint PRODUCT_CREATE: {}'.format(str(e)))
            record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
            raise UserError('Error: {}'.format(str(e)))
