            record.mark_as_syncing('odoo')
            for product_image in record.product_image_ids:
                if product_image.product_tmpl_id and product_image.product_tmpl_id.x_external_id and (not product_image.x_external_id):
                    product_image_response = base_automation.connector_id.execute_endpoint('PRODUCT_IMAGE_CREATE', record=product_image)
                    _logger.info('Response del endpoint PRODUCT_IMAGE_CREATE {}'.format(product_image_response))
                    if 200 <= product_image_response.get('status_code') < 300:
                        product_image.write(product_image_response['values'])
                        _logger.info('Imagen {} sincronizado!.'.format(product_image.name))
                        if product_image.product_variant_ids:
                            variant_response = base_automation.connector_id.execute_endpoint('PRODUCT_IMAGE_VARIANT_PATCH', record=product_image)
                            _logger.info('PRODUCT_IMAGE_VARIANT_PATCH')
                            _logger.info(variant_response)
                            if 200 <= variant_response.get('status_code') < 300:
                                if not isinstance(variant_response['values'], list):
                                    product_image.product_variant_ids.write(variant_response['values'])
                                else:
                                    for variant, vals in zip(product_image.product_variant_ids, variant_response['values']):
                                        variant.write(vals)
                            else:
                                product_image.product_variant_ids.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
