_logger.info('RA Actualizando Producto.')
PRICE_FIELDS = {'list_price'}
for record in records:
    if env.company.external_id and env.company.bearer_token and (record.company_id == env.company):
        name = record.name
        _logger.info('Actualizando Producto: {}'.format(name))
        if env.context.get('not_execute_product_base_automation', False):
            _logger.info('not_execute_product_base_automation esta en el contexto. No ejecutar RA.')
            continue
        try:
            modified_fields = base_automation.with_context(ignore_computed_fields=True)._get_trigger_fields(record)
            _logger.info('Campos a actualizar {}, Company {}'.format(modified_fields, env.company.name))
            modified_fields = [field for field in modified_fields if field != 'attribute_line_ids']
            if not modified_fields:
                continue
            price_fields_modified = [f for f in modified_fields if f in PRICE_FIELDS]
            product_fields_modified = [f for f in modified_fields if f not in PRICE_FIELDS]
            if not record.can_sync_to_store():
                _logger.info('Producto con ID {} ya está siendo sincronizado desde la tienda, saltando.'.format(record.id))
                continue
            record.mark_as_syncing('odoo')
            if product_fields_modified:
                code = 'PRODUCT_UPDATE'
                endpoint = env['solt.api.endpoint'].search([('code', '=', code), ('connector_id', '=', base_automation.connector_id.id)], limit=1)
                if not endpoint:
                    msg = 'Endpoint con código {} no configurado.'.format(code)
                    _logger.error(msg)
                    raise UserError(msg)
                response = endpoint.with_context(modified_fields=product_fields_modified).execute_request(record=record)
                _logger.info('Response {}: {}'.format(code, response))
                if 200 <= response.get('status_code') < 300:
                    record.write(response['values'])
                    if isinstance(response['raw_response'], dict) and record.product_brand_id:
                        record.product_brand_id.write({'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_exclud_from_sync': False, 'x_store_external_id': env.company.external_id, 'company_id': env.company.id})
                    record.create_product_variants_from_json(response['raw_response'], update_from_store=False)
                elif response.get('status_code') == 402:
                    record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                    _logger.error('Error 402 en {}: {}'.format(code, response.get('error_message', '')))
                elif response.get('status_code') in (422, 404):
                    _logger.error('Error {} en {}: {}'.format(response.get('status_code'), code, response.get('error_message', '')))
                else:
                    record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                    _logger.error('Error en {}: {}'.format(code, response.get('error_message', '')))
                _logger.info('Endpoint {} finalizado para {}.'.format(code, record.name))
            if price_fields_modified:
                _logger.info('Campos de precio modificados {}. Sincronizando precios de variantes con TN...'.format(price_fields_modified))
                code_price = 'PRODUCT_VARIANT_PRICE_PATCH'
                endpoint_price = env['solt.api.endpoint'].search([('code', '=', code_price), ('connector_id', '=', base_automation.connector_id.id)], limit=1)
                if not endpoint_price:
                    _logger.warning('Endpoint {} no configurado. No se actualizará el precio en TN.'.format(code_price))
                else:
                    price_response = endpoint_price.execute_request(record=record)
                    _logger.info('Response {}: {}'.format(code_price, price_response))
                    if 200 <= price_response.get('status_code') < 300:
                        _logger.info('Precios sincronizados en TN para {}.'.format(record.name))
                    else:
                        _logger.error('Error en {}: {}'.format(code_price, price_response.get('error_message', '')))
                        record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
            _logger.info('Producto {} sincronizado!.'.format(record.name))
        except Exception as e:
            _logger.error('Error al actualizar Producto: {}'.format(str(e)))
            record.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
            raise UserError('Error: {}'.format(str(e)))
    else:
        _logger.info('RA Actualizar productos. Empresa {} no está asociada a una tienda en TN.'.format(env.company.name))

