for record in records:
    if env.company.external_id and env.company.bearer_token and (record.company_id == env.company):
        name = record.product_id.display_name
        _logger.info('Ajuste de inventario a la Variante de producto: {}'.format(name))
        if env.context.get('not_execute_quants_base_automation', False):
            _logger.info('not_execute_quants_base_automation esta en el contexto. No ejecutar RA.')
            continue
        try:
            modified_fields = base_automation.with_context(ignore_computed_fields=True)._get_trigger_fields(record)
            _logger.info('Campos a actualizar {}'.format(modified_fields))
            if modified_fields:
                _logger.info('Value de quantity {}'.format(record.quantity))
                quantity = 0
                request_data = {'action': 'replace', 'value': quantity, 'id': record.product_id.x_external_id, 'location_id': record.warehouse_id.x_external_id}
                inventory_level = record.product_id._get_total_inventory_level_product_api(warehouse_external_id=record.warehouse_id.x_external_id)
                if inventory_level:
                    quantity = inventory_level[0].get('stock')
                request_data.update({'value': quantity})
                if quantity == 0:
                    code = 'VARIANT_PROD_REPLACE_STOCKOUT_POST'
                if quantity > 0:
                    code = 'VARIANT_PROD_REPLACE_STOCK_POST'
                if quantity < 0:
                    _logger.info('quitar stock')
                endpoint = env['solt.api.endpoint'].search([('code', '=', code), ('connector_id', '=', base_automation.connector_id.id)], limit=1)
                if not endpoint:
                    msg = 'Endpoint con código {} no configurado, para actualizar el stock de los productos.'.format(code)
                    _logger.info(msg)
                    raise UserError(msg)
                if not record.product_tmpl_id.can_sync_to_store():
                    _logger.info('Producto con ID {} ya está siendo sincronizada desde la tienda, saltando sincronización.'.format(record.product_tmpl_id.id))
                    continue
                record.product_tmpl_id.mark_as_syncing('odoo')
                response = endpoint.execute_request(record=record, request_data=request_data)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    if isinstance(response['values'], list):
                        for vals in response['values']:
                            record.product_id.write(vals)
                elif response.get('status_code') == 402:
                    record.product_id.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                    _logger.error('Error ejecutando endpoint {}: {}'.format(code, response.get('error_message', '')))
                elif response.get('status_code') == 422 or response.get('status_code') != 404:
                    _logger.error('Error ejecutando endpoint {}: {}'.format(code, response.get('error_message', '')))
                    raise UserError('Error ejecutando endpoint {}: {}'.format(code, response.get('error_message', '')))
                else:
                    record.product_id.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                    _logger.error('Error ejecutando endpoint {}: {}'.format(code, response.get('error_message', '')))
                _logger.info('Ejecución del endpoint {} finalizada.'.format(code))
                _logger.info('Ajuste de inventario a Variante de producto {} sincronizado!.'.format(name))
        except Exception as e:
            _logger.error('Error al Ajuste de inventario a Variante de producto {}: {}'.format(name, str(e)))
            record.product_id.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
            raise UserError('Error: {}'.format(str(e)))
    else:
        _logger.info('RA Ajuste de inventario de una variante producto. Empresa {} no esta asociada a una tienda en TN.'.format(env.company.name))

