                response = action_id.connector_id.with_company(env.company).with_user(admin_user).execute_endpoint('SALE_ORDER_GET_SINGLE', record=record, data=data)
                _logger.info('SALE_ORDER_GET_SINGLE {}'.format(response))
                if 200 <= response.get('status_code') < 300:
                    if isinstance(response['values'], list):
                        value = response['values'][0]
                    if isinstance(response['values'], dict):
                        value = response['values']
                    commitment_date = value.get('commitment_date')
                    val['commitment_date'] = commitment_date
                    to_create_values.append(value)
                    order_response_dict[str(val.get('x_external_id'))] = response['raw_response']
                else:
                    _logger.error('Error al ejecutar endpoint SALE_ORDER_GET_SINGLE: {}'.format(response.get('error_message', '')))
            else:
                order_ids |= order_id
                _logger.info('Orden con ID Externo {} ya fue sincronizado!'.format(val['x_external_id']))
    if to_create_values:
        _logger.info('to create: {}'.format(to_create_values))
        order_ids = env['sale.order'].with_context(mail_create_nosubscribe=True).with_company(env.company).sudo().create(to_create_values)
    _logger.info('Items importadas {}'.format(len(res['values'])))
    _logger.info('Items creados {}'.format(len(order_ids)))
    if order_ids:
        _logger.info('Actualizar los campos personalizados')
        for order in order_ids:
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_ORDERS_GET_VALUES', record=order)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info('Campo personalizado encontrado {}'.format(field_odoo_name))
                        val.update({field_odoo_name: response_data.get('value')})
                        order.write(val)
            else:
                _logger.error('Error al ejecutar endpoint CUSTOM_FIELD_ORDERS_GET_VALUES: {}'.format(response.get('error_message', '')))
            if order.state == 'draft':
                _logger.info('Orden a confirmar {}'.format(order.order_number))
                order.tiendanube_create_initial_stock_quants_from_order(order_response_dict)
                order.action_confirm()
                order.tiendanube_sync_picking_from_order(order_response_dict)
                if order.delivery_status == 'full':
                    order.action_lock()
    _logger.info('Crear los webhooks')
    for wh_event in ['order/created', 'order/updated', 'order/cancelled', 'order/fulfilled', 'order/paid', 'order/edited', 'fulfillment/updated']:
        wh_event_id = env['solt.register.webhook'].with_context(active_test=False).search([('event', '=', wh_event), ('company_id', '=', env.company.id)])
        if wh_event_id and wh_event_id.x_state_sync == 'yes':
            continue
        wh_event_id._register_webhook(action_id.connector_id)
else:
    _logger.error('Conector no configurado')

if not env.company.external_id or not env.company.bearer_token:
    raise UserError('La empresa {} no está sincronizada con una tienda.'.format(env.company.name))
action_id = env['ir.actions.server'].search([('use_for_initial_export', '=', True)], limit=1)
_logger.info(env.context.get('default_connector_id', False))
if action_id and action_id.connector_id:
    product_ids = env['product.template'].sudo()
    to_create_variant_product_ids = env['product.product'].sudo()
    product_to_export_ids = env['product.template'].with_company(env.company).search([('sale_ok', '=', True), ('x_exclud_from_sync', '=', False), ('x_external_id', 'in', [False, '']), ('company_id', '=', env.company.id)])
    _logger.info('Creando productos en TN...')
    for product in product_to_export_ids:
        if product.standard_price <= 0 and product.product_variant_count == 1:
            raise UserError('El costo del producto {} es {}. El costo debe ser mayor que 0.'.format(product.name, product.standard_price))
        _logger.info('Crear producto en TN: {}'.format(product.name))
        response = action_id.connector_id.execute_endpoint('PRODUCT_CREATE', record=product)
        _logger.info(response)
        if 200 <= response.get('status_code') < 300:
            product.write(response['values'])
            if isinstance(response['raw_response'], dict) and response['raw_response'].get('brand', ''):
                product.product_brand_id.write({'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_exclud_from_sync': False, 'x_store_external_id': env.company.external_id, 'company_id': env.company.id})
            to_create_variant_product_ids |= product.with_context(not_execute_product_base_automation=True).create_product_variants_from_json(response['raw_response'], update_from_store=True)
            product_ids |= product
        else:
            product.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
            _logger.error('Error ejecutando endpoint PRODUCT_CREATE: {}'.format(response.get('error_message', '')))
    _logger.info('Productos procesados {}'.format(len(product_to_export_ids)))
    _logger.info('Productos sincronizados {}'.format(len(product_ids)))
    _logger.info('Variantes sincronizadas {}'.format(len(to_create_variant_product_ids)))
    if product_ids:
        all_products = product_ids
        for product in all_products:
            _logger.info('Endpoint CUSTOM_FIELD_PROD_GET_VALUES')
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_PROD_GET_VALUES', record=product)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info('Campo personalizado encontrado {}'.format(field_odoo_name))
                        val.update({field_odoo_name: response_data.get('value')})
                        product.write(val)
            else:
                _logger.error('Error al ejecutar endpoint CUSTOM_FIELD_PROD_GET_VALUES: {}'.format(response.get('error_message', '')))
    if to_create_variant_product_ids:
        product_variant_ids = to_create_variant_product_ids
        for variant in product_variant_ids:
            _logger.info('Endpoint CUSTOM_FIELD_VARIANT_GET_VALUES')
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_VARIANT_GET_VALUES', record=variant)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info('Campo personalizado encontrado {}'.format(field_odoo_name))
                        val.update({field_odoo_name: response_data.get('value')})
                        variant.write(val)
            else:
                _logger.error('Error al ejecutar endpoint CUSTOM_FIELD_VARIANT_GET_VALUES: {}'.format(response.get('error_message', '')))
else:
    _logger.error('Conector no configurado')

if not env.company.external_id or not env.company.bearer_token:
    raise UserError('La empresa {} no está sincronizada con una tienda.'.format(env.company.name))
action_id = env['ir.actions.server'].search([('use_for_initial_import', '=', True)], limit=1)
_logger.info(env.context.get('default_connector_id', False))
if action_id and action_id.connector_id:
    res = action_id.connector_id.execute_endpoint('PRODUCT_ALL_GET', record=record)
    to_create_values = []
    to_write_values = []
    product_ids = env['product.template'].sudo()
    sku_found_product_ids = env['product.template'].sudo()
    if isinstance(res['values'], list):
        for val in res['values']:
            product_id = env['product.template'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
            if product_id:
                _logger.info('Producto con ID Externo {} ya fue sincronizado!'.format(val['x_external_id']))
                continue
            _logger.info(val)
            if val['default_code'] or val['name']:
                if val['default_code']:
                    domain = [('default_code', '=', val['default_code'])]
                else:
                    domain = [('name', '=', val['name'])]
                product_id = env['product.template'].with_company(env.company).search(domain, limit=1)
                _logger.info(product_id)
                if not product_id:
                    _logger.info('Producto con sku {} no encontrado!'.format(val['default_code']))
                    to_create_values.append({'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_store_external_id': env.company.external_id, **val})
                else:
                    product_id.with_context(not_execute_product_base_automation=True).write({'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_store_external_id': env.company.external_id, **val})
                    sku_found_product_ids |= product_id
                    _logger.info('Producto con sku {} encontrado y actualizado!'.format(val['default_code']))
    sync_values = {'x_state_sync': 'yes', 'x_date_last_sync': datetime.datetime.now(), 'x_store_external_id': env.company.external_id}
    if to_create_values:
        product_ids = env['product.template'].sudo().with_context(not_execute_product_base_automation=True).create(to_create_values)
    _logger.info('Items importadas {}'.format(len(res['values'])))
    _logger.info('Items creados {}'.format(len(to_create_values)))
    if product_ids or sku_found_product_ids:
        all_products = product_ids | sku_found_product_ids
        raw_response = []
        if isinstance(res['raw_response'], dict) and 'items' in res['raw_response']:
            raw_response = res['raw_response'].get('items')
        elif isinstance(res['raw_response'], list):
            raw_response = res['raw_response']
        product_variant_ids = all_products.with_context(not_execute_product_base_automation=True).create_product_variants_from_json(raw_response)
        _logger.info('Variantes creadas {}'.format(len(product_variant_ids)))
        for product in all_products:
            _logger.info('Endpoint CUSTOM_FIELD_PROD_GET_VALUES')
            response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_PROD_GET_VALUES', record=product)
            _logger.info(response)
            if 200 <= response.get('status_code') < 300:
                for response_data, val in zip(response['raw_response'], response['values']):
                    field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                    if field_odoo_id:
                        field_odoo_name = field_odoo_id.name
                        _logger.info('Campo personalizado encontrado {}'.format(field_odoo_name))
                        val.update({field_odoo_name: response_data.get('value')})
                        product.write(val)
            else:
                _logger.error('Error al ejecutar endpoint CUSTOM_FIELD_PROD_GET_VALUES: {}'.format(response.get('error_message', '')))
        if product_variant_ids:
            for variant in product_variant_ids:
                _logger.info('Endpoint CUSTOM_FIELD_VARIANT_GET_VALUES')
                response = action_id.connector_id.execute_endpoint('CUSTOM_FIELD_VARIANT_GET_VALUES', record=variant)
                _logger.info(response)
                if 200 <= response.get('status_code') < 300:
                    for response_data, val in zip(response['raw_response'], response['values']):
                        field_odoo_id = env['ir.model.fields'].sudo().search(['|', ('x_external_id', '=', response_data.get('id')), ('x_key', '=', response_data.get('key'))])
                        if field_odoo_id:
                            field_odoo_name = field_odoo_id.name
                            _logger.info('Campo personalizado encontrado {}'.format(field_odoo_name))
                            val.update({field_odoo_name: response_data.get('value')})
                            variant.write(val)
                else:
                    _logger.error('Error al ejecutar endpoint CUSTOM_FIELD_VARIANT_GET_VALUES: {}'.format(response.get('error_message', '')))
else:
    _logger.error('Conector no configurado')

if not env.company.external_id or not env.company.bearer_token:
    raise UserError('La empresa {} no está sincronizada con una tienda.'.format(env.company.name))
action_id = env['ir.actions.server'].search([('use_for_initial_export', '=', True)], limit=1)
_logger.info(env.context.get('default_connector_id', False))
if action_id and action_id.connector_id:
    connector = action_id.connector_id
    res = connector.execute_endpoint('PRODUCT_ALL_GET', record=record)
    product_ids = env['product.template'].sudo()
    if isinstance(res['values'], list):
        for val in res['values']:
            product_id = env['product.template'].search([('x_external_id', '=', val['x_external_id'])], limit=1)
            if product_id:
                product_ids |= product_id
                _logger.info('Producto con ID Externo {} encontrado sincronizado!'.format(val['x_external_id']))
            _logger.info(val)
    _logger.info('Productos encontrados: {}'.format(len(res['values'])))
    if product_ids:
        for product in product_ids:
            _logger.info('Sincronizando imágenes del producto ID: {} - {}'.format(product.id, product.name))
            if product.x_state_sync != 'yes':
                _logger.info("Producto {} no está en estado sync 'yes', saltando.".format(product.id))
                continue
            try:
                for product_image in product.product_image_ids:
                    if product_image.product_tmpl_id and product_image.product_tmpl_id.x_external_id and (not product_image.x_external_id):
                        _logger.info("Creando imagen '{}' en TN...".format(product_image.name))
                        image_response = connector.execute_endpoint('PRODUCT_IMAGE_CREATE', record=product_image)
                        _logger.info('Response PRODUCT_IMAGE_CREATE: {}'.format(image_response))
                        if 200 <= image_response.get('status_code', 0) < 300:
                            product_image.write(image_response['values'])
                            _logger.info("Imagen '{}' sincronizada correctamente.".format(product_image.name))
                            if product_image.product_variant_ids:
                                variant_response = connector.execute_endpoint('PRODUCT_IMAGE_VARIANT_PATCH', record=product_image)
                                _logger.info('Response PRODUCT_IMAGE_VARIANT_PATCH: {}'.format(variant_response))
                                if 200 <= variant_response.get('status_code', 0) < 300:
                                    if not isinstance(variant_response['values'], list):
                                        product_image.product_variant_ids.write(variant_response['values'])
                                    else:
                                        for variant, vals in zip(product_image.product_variant_ids, variant_response['values']):
                                            variant.write(vals)
                                else:
                                    product_image.product_variant_ids.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                                    _logger.error('Error PRODUCT_IMAGE_VARIANT_PATCH: {}'.format(variant_response.get('error_message', '')))
                        else:
                            product_image.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                            _logger.error('Error PRODUCT_IMAGE_CREATE: {}'.format(image_response.get('error_message', '')))
            except Exception as e:
                _logger.error('Error al sincronizar imágenes del producto {}: {}'.format(product.id, str(e)))
                product.write({'x_date_last_sync': datetime.datetime.now(), 'x_state_sync': 'error'})
                continue
        _logger.info('Exportación masiva de imágenes finalizada.')
else:
    _logger.error('Conector no configurado')
